  const p=mine.filter(q=>evalTrade(tid,[q.id],[],0,{get:[k]}).ok&&capPayAs(tid,[q.id],[])<=capOf(G.year)).sort((a,b)=>b.sal-a.sal)[0]; ok(p,'준비 실패: 받아들일 선수 없음');
