  const A=G.players[G.draftClass[1]], Bp=G.players[G.draftClass[2]]; A.gmSeen=G.year; draftClaims(); const k0=_dcc.k; delete A.gmSeen; Bp.gmSeen=G.year; draftClaims(); ok(_dcc.k!==k0,'관찰 후보가 바뀌었는데 캐시 유지');
