  const q=domestic(A).find(x=>x!==p&&!x.isP); q.regD={y:G.year,n:52,il:0}; q.tLog=[{y:G.year,d:G.cal.open+10,f:B,t:A}]; ok(regNT(q,A)===0,'이적한 해 옛 저장 등록일을 지명 구단 몫으로 인정'); delete q.tLog; ok(regNT(q,A)===52,'이적 없으면 전부 인정');
