T('[검수 11-08d] 순번 하락 제재를 함께 받은 두 구단의 1라운드 지명권은 실제 순번처럼 서로 다른 순번으로 평가한다',()=>{ fresh(); G.draft={y:G.year,done:true}; const o=standingsNow().map(x=>x.tid).reverse(); team(o[0]).pickPen=G.year+1; team(o[1]).pickPen=G.year+1; try{ const a=pkSlot(o[0],1), b=pkSlot(o[1],1), P=penOrder(o,[o[0],o[1]]); ok(a!==b,'두 구단 모두 '+a+'순번'); ok(a===P.indexOf(o[0])&&b===P.indexOf(o[1]),'실제 순번 계산과 다름 '+a+'/'+b); }finally{ team(o[0]).pickPen=null; team(o[1]).pickPen=null; } });
