  const a=corePool(t.id).filter(q=>healthy(q)&&!q.foreign).sort((x,y)=>ovr(x)-ovr(y))[0]; const mk=()=>({id:'oM',from:t.id,give:[a.id],get:[mine.id],exp:G.day+3,day:G.day,blk:true,adv:{sc:'옛 보고'},pot:'옛 추정'});
