  const up=()=>playersOf(U).filter(p=>!p.isP&&!isC(p)&&canUp(p));
  const [c1]=setC(1); low(c1); const r=up()[0]; ok(r,'준비 실패: 올릴 야수 없음'); high(r); entryUpgrade(U,[r],'점검');
