  const cs2=setC(2); cs2.forEach(low); const m=G.mgr[U]; m.ego=20; m.rel=95; m.pl={listen:true}; let msg='', x=null; for(const q of up()){ high(q); msg=reqEntry(q.id,true); if(q.e1){ x=q; break; } }
