  const p=mk(55,600,3); while(rosterN(t)<ROSTER_MAX)newPlayer({age:22,isP:false,base:40,pot:42,team:t}); G.fa.ai[p.id]={[t]:{annual:1020,years:3}}; ok(agMatchOffer(p.id)===null,'정원이 찬 구단 제안에 맞춰 연봉을 올림');
