  ok(n('김')>.17&&n('김')<.27&&n('이')>.11&&n('박')>.06,'흔한 성씨 비중 김 '+n('김').toFixed(3)+' 이 '+n('이').toFixed(3)+' 박 '+n('박').toFixed(3)); for(const c of ['맹','인','육'])ok(n(c)<.003,'희성 '+c+' '+n(c));
